		if (vc == Cnd_maker_flg) return doCnd_maker_flg_VC(info);
		if (vc == Cnd_bp_cd) return doCnd_bp_cd_VC(info);
		if (vc == Cnd_bp_nm) return doCnd_bp_nm_VC(info);
		if (vc == Cnd_ein) return doCnd_ein_VC(info);
